#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe smtp-catch-a-duplicate-from-a-lost-reply. Do not edit.
set -e
cd "$(dirname "$0")"
printf '%s' 'control-token-0123456789abcdefghij' > token.txt
cat > order.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 1042 confirmed
Message-ID: <order-1042@shop.example.com>

Thank you for order 1042.
EOF
cat > tries.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Usage: sh tries.sh TRACE. Waits (at most 10 s) until every exchange in surl's --trace-ascii
# file has ended, then, for each SMTP exchange that reached DATA (a try), prints what the server
# sent from its 354 on, each line after the bytes the server had sent by the end of it, and
# where the server stored the message or cut the connection.
trace=$1
tries=0
until [ "$(grep -c ' opened: ' "$trace")" -le "$(grep -c ' ended; ' "$trace")" ]; do
  tries=$((tries + 1))
  if [ "$tries" -gt 10 ]; then echo "an exchange has not ended" >&2; exit 1; fi
  sleep 1
done
tr -d '\r' < "$trace" | awk '
  / opened: smtp / { smtp[$1] = 1 }
  / => Send data, / { take = smtp[$1] ? $1 : ""; sent[$1] += $5; next }
  / \* Message stored/ && ($1 in try) { print "try " try[$1] ": message stored"; next }
  / cut after / && ($1 in try) { n = $0; sub(/.* cut after /, "", n); sub(/ bytes.*/, "", n); print "try " try[$1] ": cut after " n " bytes"; next }
  /^#/ { take = ""; next }
  take != "" && /^[0-9a-f][0-9a-f][0-9a-f][0-9a-f]: / {
    line = substr($0, 7)
    if (!(take in try) && index(line, "354 ") == 1) try[take] = ++count
    if (take in try) print "try " try[take] ": " sent[take] " " line
  }'
EOF
surl --trace-ascii smtp.trace --mail-domain example.com --mailbox shop@example.com:shoppass --mailbox ann@example.com:annpass --control http://127.0.0.1:8082 --control-token-file token.txt smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS -o /dev/null -w "%{http_code}\n" -H "Authorization: Bearer control-token-0123456789abcdefghij" -H "Content-Type: text/plain" -d "drop;scheme=smtp;after-bytes=320;close=graceful;times=1" http://127.0.0.1:8082/v1/faults && curl -sS --crlf -m 10 --retry 1 --retry-all-errors --retry-delay 1 -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml -w "%{response_code} %{num_retries}\n" smtp://127.0.0.1:8080/shop.example.com && curl -sS -u ann@example.com:annpass -X "UID SEARCH HEADER Message-ID <order-1042@shop.example.com>" imap://127.0.0.1:8081/INBOX
kill $(jobs -p)
